//! The proxy decides every shared hook-rule vector the way every other layer
//! does.
//!
//! Two fixtures under `packages/shared-types/fixtures/`, both generated by
//! `packages/shared-types/scripts/generate-guardrail-fixtures.ts`:
//!
//! * `guardrail-layer-vectors.json` — guardrails, what the control plane
//!   serves for them, one tool call, and the decision (`block` naming the
//!   enforcing rule, `warn` naming the shadow rule, `allow`). The emitted hook
//!   gates, gate-js, intutic-clawde, the MCP proxy and the hosted hook gate run
//!   the same file; here each vector's SOP entries are served by a stand-in
//!   control plane on `GET /api/v1/workspace/sops-policy` and fetched by the
//!   gateway resolver — the real feed and the real parser — the caller's
//!   member role is read from the stand-in's `GET /api/v1/auth/key-context`
//!   (upper case, as the control plane names it; absent for a vector whose
//!   role is not known) by the read `proxy.rs` makes, and the set is scoped
//!   to it as `proxy.rs` scopes it; then the call is
//!   decided directly, inside an Anthropic and an OpenAI response body, and
//!   inside an Anthropic and an OpenAI stream whose arguments arrive in
//!   fragments, through the response gate's own hold.
//! * `hook-rule-vectors.json` — single rules and the calls they must and must
//!   not fire on, which the four regex matchers already run.
//!
//! A missing fixture is a failure, not a skip: a skip would read as "every
//! vector agrees". One `#[tokio::test]`, because gateway mode is a set-once
//! process-global.

use std::net::SocketAddr;
use std::path::PathBuf;
use std::sync::Arc;

use axum::extract::State;
use axum::response::Json;
use axum::routing::get;
use axum::Router;
use serde::Deserialize;
use serde_json::{json, Value};

use intutic_proxy::config::ResponseGateConfig;
use intutic_proxy::credential::RequestCredential;
use intutic_proxy::gateway::{init_gateway_config, GatewayConfig};
use intutic_proxy::key_context::fetch_member_role;
use intutic_proxy::plugins::hook_rules::{parse_line, CallInput, HookRuleDecision, HookRuleSet};
use intutic_proxy::plugins::response_gate::{
    gate_response_hook_rules, gate_stream_line_hook_rules, DenialReason,
};
use intutic_proxy::plugins::sql_guard::StreamHold;
use intutic_proxy::sops::{all_sops_for_workspace, Sop};

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("shared-types")
        .join("fixtures")
        .join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e} — this test would assert nothing", path.display()))
}

#[derive(Deserialize)]
struct LayerFile {
    vectors: Vec<LayerVector>,
}

#[derive(Deserialize)]
struct LayerVector {
    name: String,
    served: Served,
    role: Option<String>,
    #[serde(rename = "toolCall")]
    tool_call: ToolCall,
    expected: Expected,
}

#[derive(Deserialize)]
struct Served {
    sops: Vec<Value>,
}

#[derive(Deserialize)]
struct ToolCall {
    tool: String,
    #[serde(rename = "toolInput")]
    tool_input: Value,
}

#[derive(Deserialize, Debug, PartialEq, Eq)]
struct Expected {
    decision: String,
    #[serde(rename = "ruleId")]
    rule_id: Option<String>,
}

fn outcome(d: &HookRuleDecision) -> Expected {
    if let Some(hit) = &d.refuse {
        return Expected {
            decision: "block".into(),
            rule_id: Some(hit.rule_id.clone()),
        };
    }
    match d.shadow.first() {
        Some(hit) => Expected {
            decision: "warn".into(),
            rule_id: Some(hit.rule_id.clone()),
        },
        None => Expected {
            decision: "allow".into(),
            rule_id: None,
        },
    }
}

/// The SSE lines of one Anthropic tool call, its input split across two
/// `input_json_delta` fragments the way the API streams it (with the space
/// after each colon a model's own serialisation carries).
fn anthropic_stream(tool: &str, input: &Value) -> Vec<String> {
    let args = serde_json::to_string_pretty(input)
        .unwrap()
        .replace('\n', "");
    let (a, b) = args.split_at(args.len() / 2);
    let mut lines = vec![
        "event: content_block_start".to_string(),
        format!(
            "data: {}",
            json!({"type":"content_block_start","index":1,"content_block":{"type":"tool_use","id":"toolu_lv","name":tool,"input":{}}})
        ),
        String::new(),
    ];
    for part in [a, b] {
        lines.push("event: content_block_delta".to_string());
        lines.push(format!(
            "data: {}",
            json!({"type":"content_block_delta","index":1,"delta":{"type":"input_json_delta","partial_json":part}})
        ));
        lines.push(String::new());
    }
    lines.push("event: content_block_stop".to_string());
    lines.push(format!(
        "data: {}",
        json!({"type":"content_block_stop","index":1})
    ));
    lines.push(String::new());
    lines
}

/// The SSE lines of one OpenAI chat tool call, arguments in two deltas.
fn openai_stream(tool: &str, input: &Value) -> Vec<String> {
    let args = input.to_string();
    let (a, b) = args.split_at(args.len() / 2);
    let chunk = |delta: Value, finish: Value| {
        format!(
            "data: {}",
            json!({"id":"chatcmpl-lv","object":"chat.completion.chunk","choices":[{"index":0,"delta":delta,"finish_reason":finish}]})
        )
    };
    let mut lines = vec![chunk(
        json!({"tool_calls":[{"index":0,"id":"call_lv","type":"function","function":{"name":tool,"arguments":""}}]}),
        Value::Null,
    )];
    for part in [a, b] {
        lines.push(chunk(
            json!({"tool_calls":[{"index":0,"function":{"arguments":part}}]}),
            Value::Null,
        ));
    }
    lines.push(chunk(json!({}), json!("tool_calls")));
    lines.push("data: [DONE]".to_string());
    lines
}

/// One stream through the response gate as `proxy.rs` drives it: the name
/// check on every line, then the hold. Returns the decision and whether the
/// tool call's lines were released to the client.
fn stream_outcome(
    cfg: &ResponseGateConfig,
    set: &HookRuleSet,
    lines: Vec<String>,
) -> (Expected, bool) {
    let mut hold = StreamHold::new(Vec::new()).with_hook_rules(set.clone());
    let mut seen = HookRuleDecision::default();
    let mut released: Vec<String> = Vec::new();
    for line in lines {
        if let Some((denial, shadow)) = gate_stream_line_hook_rules(cfg, &line, set) {
            seen.shadow.extend(shadow);
            if let Some(d) = denial {
                let DenialReason::HookRule(hit) = d.reason else {
                    panic!("a hook-rule refusal of another kind: {:?}", d.reason);
                };
                seen.refuse = Some(hit);
                return (outcome(&seen), false);
            }
        }
        let step = hold.push(line);
        seen.shadow.extend(step.hook_shadow);
        if let Some((hit, _)) = step.refuse_hook {
            seen.refuse = Some(hit);
            return (outcome(&seen), false);
        }
        released.extend(step.emit);
    }
    assert!(
        hold.take_unfinished().is_none(),
        "the hold kept a complete block"
    );
    let call_released = released
        .iter()
        .any(|l| l.contains("toolu_lv") || l.contains("call_lv"));
    (outcome(&seen), call_released)
}

/// Each vector's served SOPs and caller role.
type StandIn = Arc<Vec<(Vec<Value>, Option<String>)>>;

/// The bearer names the vector: `vk_lv<index>_…`.
fn vector_index(headers: &axum::http::HeaderMap) -> usize {
    headers
        .get("authorization")
        .and_then(|v| v.to_str().ok())
        .and_then(|a| a.split("vk_lv").nth(1))
        .and_then(|rest| rest.split('_').next())
        .and_then(|n| n.parse().ok())
        .expect("a vector-indexed virtual key")
}

async fn stand_in(vectors: StandIn) -> SocketAddr {
    async fn sops_policy(
        State(vectors): State<StandIn>,
        headers: axum::http::HeaderMap,
    ) -> Json<Value> {
        let index = vector_index(&headers);
        Json(json!({ "workspaceId": format!("ws_lv{index}"), "sops": vectors[index].0 }))
    }
    async fn key_context(
        State(vectors): State<StandIn>,
        headers: axum::http::HeaderMap,
    ) -> Json<Value> {
        let index = vector_index(&headers);
        let mut body = json!({ "workspaceId": format!("ws_lv{index}") });
        if let Some(role) = &vectors[index].1 {
            body["role"] = json!(role.to_uppercase());
        }
        Json(body)
    }
    let app = Router::new()
        .route("/api/v1/workspace/sops-policy", get(sops_policy))
        .route("/api/v1/auth/key-context", get(key_context))
        .with_state(vectors);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    addr
}

#[tokio::test]
async fn the_proxy_decides_every_shared_hook_rule_vector_as_every_layer_does() {
    // ── guardrail-layer-vectors.json, through the served feed ────────────
    let file: LayerFile = serde_json::from_str(&fixture("guardrail-layer-vectors.json"))
        .expect("the layer vector file parses");
    assert!(
        file.vectors.len() >= 32,
        "only {} layer vectors",
        file.vectors.len()
    );
    assert!(
        file.vectors.iter().any(|v| v.role.is_none()
            && v.served
                .sops
                .iter()
                .any(|s| s.to_string().contains(r#"\"roles\":"#))),
        "no vector holds a caller whose role is unknown to a scoped rule"
    );
    for d in ["block", "warn", "allow"] {
        assert!(
            file.vectors.iter().any(|v| v.expected.decision == d),
            "no {d} vector"
        );
    }

    init_gateway_config(GatewayConfig {
        require_vk: true,
        ..Default::default()
    });
    let served: StandIn = Arc::new(
        file.vectors
            .iter()
            .map(|v| (v.served.sops.clone(), v.role.clone()))
            .collect(),
    );
    let addr = stand_in(served).await;
    let cp = format!("http://{addr}");
    let client = reqwest::Client::new();
    let cfg = ResponseGateConfig::default();

    for (i, v) in file.vectors.iter().enumerate() {
        let key = RequestCredential::classify(&format!("vk_lv{i}_deadbeef"));
        let ws = format!("ws_lv{i}");
        let sops: Vec<Sop> =
            all_sops_for_workspace(&client, Some(&cp), Some(&ws), key.virtual_key(), None).await;
        assert_eq!(
            sops.len(),
            v.served.sops.len(),
            "{}: the proxy loaded {} of {} served SOPs",
            v.name,
            sops.len(),
            v.served.sops.len()
        );
        let member_role = fetch_member_role(
            &client,
            &cp,
            key.virtual_key().expect("a virtual key"),
            std::time::Duration::from_secs(5),
            None,
        )
        .await;
        assert_eq!(
            member_role.as_deref().map(str::to_lowercase),
            v.role,
            "{}: the member role read from key-context",
            v.name
        );
        let set = HookRuleSet::from_sops(&sops, "").for_member_role(member_role.as_deref());
        let tool = v.tool_call.tool.as_str();
        let input = &v.tool_call.tool_input;

        let direct = outcome(&set.decide(tool, CallInput::Parsed(input)));
        assert_eq!(direct, v.expected, "{}: decided directly", v.name);

        let anthropic = json!({"content":[{"type":"text","text":"On it."},{"type":"tool_use","id":"toolu_lv","name":tool,"input":input}]});
        let openai = json!({"choices":[{"index":0,"message":{"role":"assistant","content":null,"tool_calls":[{"id":"call_lv","type":"function","function":{"name":tool,"arguments":input.to_string()}}]},"finish_reason":"tool_calls"}]});
        for (shape, body) in [("Anthropic body", anthropic), ("OpenAI body", openai)] {
            let (denial, decision, saw_call) = gate_response_hook_rules(&cfg, Some(&body), &set);
            // A set the role filter emptied has nothing to look for.
            assert_eq!(
                saw_call,
                !set.is_empty(),
                "{}: {shape}: the call was not seen",
                v.name
            );
            assert_eq!(outcome(&decision), v.expected, "{}: {shape}", v.name);
            assert_eq!(
                denial.is_some(),
                v.expected.decision == "block",
                "{}: {shape}: refusal",
                v.name
            );
            if let Some(d) = denial {
                assert_eq!(
                    Some(d.refusal().rule),
                    v.expected.rule_id,
                    "{}: {shape}: the refusal names the rule",
                    v.name
                );
                assert_eq!(d.refusal().code.as_str(), "TOOL_DENIED");
            }
        }

        for (shape, lines) in [
            ("Anthropic stream", anthropic_stream(tool, input)),
            ("OpenAI stream", openai_stream(tool, input)),
        ] {
            let (got, released) = stream_outcome(&cfg, &set, lines);
            assert_eq!(got, v.expected, "{}: {shape}", v.name);
            assert_eq!(
                released,
                v.expected.decision != "block",
                "{}: {shape}: a refused call must never be released, an allowed one always",
                v.name
            );
        }
    }

    // ── hook-rule-vectors.json, rule by rule ─────────────────────────────
    #[derive(Deserialize)]
    struct HookFile {
        vectors: Vec<HookVector>,
    }
    #[derive(Deserialize)]
    struct HookVector {
        name: String,
        ir: Value,
        rendered: Value,
        cases: Vec<HookCase>,
    }
    #[derive(Deserialize)]
    struct HookCase {
        tool: String,
        #[serde(rename = "toolInput")]
        tool_input: Value,
        fires: bool,
    }
    let file: HookFile = serde_json::from_str(&fixture("hook-rule-vectors.json"))
        .expect("the hook-rule vector file parses");
    assert!(file.vectors.len() >= 8);
    assert!(file.vectors.iter().map(|v| v.cases.len()).sum::<usize>() >= 35);
    for v in &file.vectors {
        // The line the control plane serves for this IR (`proxyHookRule`).
        let line = json!({
            "id": "guardrail.pgr_vector",
            "tools": v.ir["tools"],
            "argContains": v.ir.get("argContains").cloned().unwrap_or(json!([])),
            "argNotContains": v.ir.get("argNotContains").cloned().unwrap_or(json!([])),
            "reason": v.rendered["reason"],
        });
        let sop = Sop {
            title: format!("GUARDRAIL:pgr_vector {}", v.name),
            hook_rules: vec![parse_line(&line.to_string())],
            ..Sop::default()
        };
        let set = HookRuleSet::from_sops(std::slice::from_ref(&sop), "");
        for c in &v.cases {
            let fired = set
                .decide(&c.tool, CallInput::Parsed(&c.tool_input))
                .refuse
                .is_some();
            assert_eq!(fired, c.fires, "{}: {} {}", v.name, c.tool, c.tool_input);
        }
    }
}
